-- Demo reporting orders: 123 completed orders, 2024-01-03 through 2026-10-17.
-- Import server/database.sql first, then this file for an existing database.
-- Includes VAT 8%; synthetic data only. Re-import skips existing demo order numbers.
-- Requires orders.invoiceTotals from the current schema. Does not change inventory.
SET NAMES utf8mb4;
SET @demo_previous_timezone = @@session.time_zone;
SET time_zone = '+07:00';
SET @demo_customer_id = (SELECT MIN(id) FROM users WHERE role = 'customer');
START TRANSACTION;
INSERT INTO orders (userId, orderNumber, items, totalAmount, shippingAddress, shippingMethod, paymentMethod, status, invoiceTotals, createdAt, updatedAt)
SELECT @demo_customer_id, 'DEMO-REPORT-20240103-001', CONVERT( USING utf8mb4), 6890000, '[DEMO] Synthetic reporting order', 'standard', 'cod', 'completed', CONVERT(0x7b2276617452617465223a382c226e6574416d6f756e74223a363337393633302c22766174416d6f756e74223a3531303337302c227368697070696e67416d6f756e74223a302c22646973636f756e74416d6f756e74223a307d USING utf8mb4), '2024-01-03 08:15:00', '2024-01-03 08:15:00'
WHERE @demo_customer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM orders WHERE orderNumber = 'DEMO-REPORT-20240103-001');
